package com.melarc.attestation

import java.nio.file.Files
import java.nio.file.Path
import java.util.concurrent.TimeUnit
import kotlin.test.assertEquals
import kotlin.test.assertTrue
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir

/**
 * The published vectors of the rider device-key protocol (SECURITY_DESIGN.md 13.6) are generated by `GenerateDeviceKeyVectors.java` on **the
 * JDK this service is pinned to** and consumed by the API's tests. This holds the committed file to a fresh run of the generator on the
 * JDK that runs this test: a JDK whose security API says otherwise, or a vectors file edited by hand, fails here. **Break caught:** a
 * vectors file that no generator produced, and a JDK update that changes what the Java security API signs or encodes.
 */
class DeviceKeyVectorsTest {
  private val vectors: Path = Path.of(checkNotNull(System.getProperty("melarc.vectors.dir")) { "melarc.vectors.dir is not set" })

  @Test
  fun `a fresh run of the generator gives the committed vectors, byte for byte`(@TempDir directory: Path) {
    val java = Path.of(System.getProperty("java.home"), "bin", "java").toString()
    val output = directory.resolve("device-key.v1.json")
    val process =
      ProcessBuilder(java, vectors.resolve("GenerateDeviceKeyVectors.java").toString())
        .directory(directory.toFile())
        .redirectOutput(output.toFile())
        .redirectError(directory.resolve("generator.err").toFile())
        .start()
    assertTrue(process.waitFor(120, TimeUnit.SECONDS), "the generator did not finish")
    assertEquals(0, process.exitValue(), Files.readString(directory.resolve("generator.err")))
    // A checkout may carry either line ending; the content is what is held.
    fun normalised(path: Path) = Files.readString(path).replace("\r\n", "\n")
    assertEquals(normalised(vectors.resolve("device-key.v1.json")), normalised(output))
  }
}
